entries[323546] = { ["name"] = "Unersättliche Raserei", ["text"] = "Pakt-Fähigkeit\nSofort 3 min Abklingzeit\nVon Euch eingesetzte Druidenzauber erhöhen 20 Sek. lang Euren Schaden und Eure Heilung um 2% sowie Euer Tempo um 1%. Dieser Effekt ist stapelbar.\n\nWenn Ihr 2 Sek. lang untätig bleibt, überwältigt Euch die Raserei, was pro Stapel 1% Eurer Gesundheit aufzehrt, Euch für 1 Sek. betäubt und den Effekt beendet." }
entries[323547] = { ["name"] = "Widerhallender Tadel", ["text"] = "Pakt-Fähigkeit\n10 Energie Nahkampfreichweite\nSofort 45 sek. Abklingzeit\nBenötigt Einhändige Nahkampfwaffe\nFügt einem Gegner (120% der Angriffskraft) Arkanschaden zu und extrahiert seine Anima, um einen Combopunkt für 45 Sek. mit Anima zu laden.\n\nSchaden verursachende Finishing-Moves, die eine Eurer Animaladung entsprechende Anzahl Combopunkte verbrauchen, funktionieren so, als ob sie 7 Combopunkte verbraucht hätten.\n\nGewährt 2 Combopunkte." }
