entries[323913] = { ["name"] = "Kräuselndes Fleisch", ["text"] = "Wenn Ihr Heilung erhaltet oder Eure Verbündeten heilt, erhaltet Ihr für 10 Sek. 1% kritische Trefferchance, bis zu 5%.\n\nWenn Ihr durch 'Runenbeschriebener Knochen' ermächtigt seid, erhaltet Ihr zusätzlich 1% kritische Trefferchance pro Stapel.\n(1s Abklingzeit)" }
entries[323914] = { ["name"] = "Klingenzwirn", ["text"] = "Eure Angriffe und Zauber haben eine Chance, Klingen um Euch wirbeln zu lassen. Diese belegen Ziele mit einer Blutung, die im Verlauf von 5 Sek. 500 Schaden verursacht.\n\nWenn Ihr durch 'Runenbeschriebener Knochen' ermächtigt seid, wird der Schaden verdoppelt." }
entries[323915] = { ["name"] = "Beständigkeit des Geprüften", ["text"] = "Nachdem Ihr 10.000 Schaden verursacht habt, erhaltet Ihr 'Beständigkeit', wodurch Ihr den nächsten Handlungsunfähigkeitseffekt, der Euch trifft, ignoriert. Wird bei Verlassen des Kampfes aufgehoben." }
entries[323916] = { ["name"] = "Schwefelemission", ["text"] = "Seelenbandefähigkeit\nWenn Ihr auf unter 20% Gesundheit fallt, versetzt Ihr Gegner in der Nähe für 3.5 Sek. in Furcht. Kann nur einmal alle 60 Sek. auftreten." }
entries[323917] = { ["name"] = "Die Liste", ["text"] = "Wenn Ihr einem Gegner 10.000 Schaden zufügt, landet er auf Eurer Todesliste.\nWenn Ihr einen Gegner auf Eurer Todesliste besiegt, erhaltet Ihr für 30 Sek. zusätzlich 100 kritischen Trefferwert, bis zu 1.000." }
