entries[323920] = { ["name"] = "Vorbescheid", ["text"] = "Einmal pro Woche schickt Emeni Euch einen Brief mit einem Vorbescheid. Erhöht bei Benutzung Euren Primärwert im Kampf gegen dieses Ziel um 5%. Geht beim Tod verloren. 3 Aufladungen." }
