entries[324164] = { ["name"] = "Recht des Todes", ["text"] = "Unbegrenzte Reichweite\nSofort\nVerderbt den anvisierten Boden und fügt Zielen in diesem Bereich im Verlauf von 10 Sek. [(5.4054% der Angriffskraft) * 11] Schattenschaden zu.\n\nBlut, Unheilig\nSolange Ihr Euch im Effektbereich aufhaltet [treffen 'Nekrotischer Stoß' und][trifft] [ Blut : 'Herzstoß' bis zu 0 zusätzliche Ziele und Ziele werden für 12 Sek. mit 'Recht des Todes' belegt ]['Geißelstoß' bis zu 7 Gegner in der Nähe des Ziels und Ziele werden für 12 Sek. mit 'Recht des Todes' belegt.] [\nWährend Ihr im Effektbereich verbleibt, trifft 'Auslöschen' bis zu 1 zusätzliches Ziel und Ziele werden für 12 Sek. mit 'Recht des Todes' belegt.]\n'Recht des Todes' verringert den Schaden, den Gegner Euch zufügen, um 2%, bis zu einem Maximum von 8%, und ihre verlorene Kraft wird Euch als Stärke gewährt." }
entries[324165] = { ["name"] = "Recht des Todes", ["text"] = "Unbegrenzte Reichweite\nSofort\nVerderbt den anvisierten Boden und fügt Zielen in diesem Bereich im Verlauf von 10 Sek. [(5.4054% der Angriffskraft) * 11] Schattenschaden zu.\n\nBlut, Unheilig\nSolange Ihr Euch im Effektbereich aufhaltet [treffen 'Nekrotischer Stoß' und][trifft] [ Blut : 'Herzstoß' bis zu 0 zusätzliche Ziele und Ziele werden für 12 Sek. mit 'Recht des Todes' belegt ]['Geißelstoß' bis zu 7 Gegner in der Nähe des Ziels und Ziele werden für 12 Sek. mit 'Recht des Todes' belegt.] [\nWährend Ihr im Effektbereich verbleibt, trifft 'Auslöschen' bis zu 1 zusätzliches Ziel und Ziele werden für 12 Sek. mit 'Recht des Todes' belegt.]\n'Recht des Todes' verringert den Schaden, den Gegner Euch zufügen, um 2%, bis zu einem Maximum von 8%, und ihre verlorene Kraft wird Euch als Stärke gewährt." }
