entries[324195] = { ["name"] = "Schreiben der Vielseitigkeit", ["text"] = "Wirken in 3.5 sek.\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeuchtende Tinte (2), Umbraltinte (8), Stille Tinte , Dunkles Pergament\nStellt ein Schreiben der Vielseitigkeit her, ein optionales Reagenz, das gewährleistet, dass auf einer hergestellten Waffe oder einem hergestellten Rüstungsteil Vielseitigkeit als Wert vorhanden ist.\nBeruf:\nInschriftenkunde der Schattenlande (40)\nLehrer:\nSchreiber Au'tehshi\nZone:\nOribos\nKosten:\n1\n50\n\nOptionales Handwerksmaterial\n\nGewährt die folgende Eigenschaft: Vielseitigkeit garantiert\nBenutzbar mit: Muster aus Shadowlands für seltene und legendäre Rüstung und Zubehör.\n\"Von Inschriftenkundigen gefertigte Schreiben können im Auktionshaus verkauft und erworben werden.\"" }
entries[324196] = { ["name"] = "Schreiben der Meisterschaft", ["text"] = "Wirken in 3.5 sek.\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeuchtende Tinte (4), Umbraltinte (6), Stille Tinte , Dunkles Pergament\nStellt ein Schreiben der Meisterschaft her, ein optionales Reagenz, das gewährleistet, dass auf einer hergestellten Waffe oder einem hergestellten Rüstungsteil Meisterschaft als Wert vorhanden ist.\nBeruf:\nInschriftenkunde der Schattenlande (40)\nLehrer:\nSchreiber Au'tehshi\nZone:\nOribos\nKosten:\n1\n50\n\nOptionales Handwerksmaterial\n\nGewährt die folgende Eigenschaft: Meisterschaft garantiert\nBenutzbar mit: Muster aus Shadowlands für seltene und legendäre Rüstung und Zubehör.\n\"Von Inschriftenkundigen gefertigte Schreiben können im Auktionshaus verkauft und erworben werden.\"" }
entries[324197] = { ["name"] = "Schreiben des kritischen Treffers", ["text"] = "Wirken in 3.5 sek.\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeuchtende Tinte (8), Umbraltinte (2), Stille Tinte , Dunkles Pergament\nStellt ein Schreiben des kritischen Treffers her, ein optionales Reagenz, das gewährleistet, dass auf einer hergestellten Waffe oder einem hergestellten Rüstungsteil kritischer Trefferwert als Wert vorhanden ist.\nBeruf:\nInschriftenkunde der Schattenlande (40)\nLehrer:\nSchreiber Au'tehshi\nZone:\nOribos\nKosten:\n1\n50\n\nOptionales Handwerksmaterial\n\nGewährt die folgende Eigenschaft: Kritischer Trefferwert garantiert\nBenutzbar mit: Muster aus Shadowlands für seltene und legendäre Rüstung und Zubehör.\n\"Von Inschriftenkundigen gefertigte Schreiben können im Auktionshaus verkauft und erworben werden.\"" }
entries[324198] = { ["name"] = "Schreiben des Tempos", ["text"] = "Wirken in 3.5 sek.\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeuchtende Tinte (6), Umbraltinte (4), Stille Tinte , Dunkles Pergament\nStellt ein Schreiben des Tempos her, ein optionales Reagenz, das gewährleistet, dass auf einer hergestellten Waffe oder einem hergestellten Rüstungsteil Tempo als Wert vorhanden ist.\nBeruf:\nInschriftenkunde der Schattenlande (40)\nLehrer:\nSchreiber Au'tehshi\nZone:\nOribos\nKosten:\n1\n50\n\nOptionales Handwerksmaterial\n\nGewährt die folgende Eigenschaft: Tempo garantiert\nBenutzbar mit: Muster aus Shadowlands für seltene und legendäre Rüstung und Zubehör.\n\"Von Inschriftenkundigen gefertigte Schreiben können im Auktionshaus verkauft und erworben werden.\"" }
