entries[324662] = { ["name"] = "Ionisiertes Plasma", ["text"] = "100 Meter Reichweite\nSofort\nKin-Tara wirft einen geladenen Speer auf das Ziel, der allen Spielercharakteren innerhalb von 5 Metern um den Einschlag 3636674 Arkanschaden zufügt und einen Bereich voll ionisiertem Plasma hinterlässt.\n\nSpielercharaktere im Effektbereich erleiden alle 1 Sek. 2424449 Arkanschaden und ihre Bewegungsgeschwindigkeit wird um 1% verringert." }
